let geoffCardCache={key:'',promise:null};
function shareRunner(item){return item&&race.horses.find(h=>h.name===item.name)||item}
function geoffShareState(){
 const s=lateMail?.selections?.[String(race.number)],report=lateMail?.meeting?.races?.find(r=>r.number===race.number),finished=report?.status==='official';
 const active=item=>item&&!report?.runners?.find(h=>horseKey(h.name)===horseKey(item.name))?.scratched,revised=s?.revisedTip&&s.revisedTip.reliable!==false&&active(s.revisedTip)?s.revisedTip:null,live=revised||(active(s?.provisionalLeader)?s.provisionalLeader:null);
 const candidates=[live,...(s?.topThree||[]),...baseline.filter(h=>h.rankable)].filter(active),seen=new Set(),activeOrder=candidates.filter(h=>{const key=horseKey(h.name);if(seen.has(key))return false;seen.add(key);return true}),msToJump=report?.startAt?Date.parse(report.startAt)-Date.now():0,ready=finished||!report?.startAt||msToJump<=600000,picks=ready?activeOrder.slice(0,3).map(shareRunner):[];
 const saved=s?(revised||s.baselineTip):null,resultRunner=finished&&saved&&report.runners.find(h=>horseKey(h.name)===horseKey(saved.name)),placing=resultRunner?.placing,winner=finished?report.winners?.[0]:null;
 const mood=!finished&&!ready?'locked':!finished?'upcoming':placing===1?'landed':placing===2||placing===3?'money':'off',title={locked:'Tips land 10 mins before jump',upcoming:"Geoff's top pick",landed:'Geoff landed it',money:'In the money',off:'Off track'}[mood];
 const sub={locked:'Final scratchings and replacements will be applied.',upcoming:'Final active top three',landed:`${saved?.display} won`,money:`${saved?.display} ran ${placingLabel(placing)}`,off:`Saved: ${saved?.display||'No tip'} · Winner: ${winner?M.title(winner.name):'unavailable'}`}[mood],dividend=placing===1?resultRunner?.winDividend:placing===2||placing===3?resultRunner?.placeDividend:null;
 const hero=shareRunner(finished?saved:(live||picks[0])),support=picks.filter(h=>h&&h.name!==hero?.name).slice(0,2);
 return {s,report,finished,ready,picks,saved,resultRunner,placing,winner,mood,title,sub,dividend,hero:ready?hero:null,support};
}
function sharePrice(h,state){if(!h)return'';if(state.finished)return state.saved?.name===h.name&&state.dividend?`${state.placing===1?'WIN':'PLACE'} $${Number(state.dividend).toFixed(2)}`:'';return Number.isFinite(h.odds)?`WIN $${Number(h.odds).toFixed(2)}`:''}
function renderGeoffShare(){
 const panel=document.getElementById('shareGeoffPanel');if(!panel||!race)return;const state=geoffShareState(),hero=state.hero;
 panel.className=`share-geoff share-${state.mood}`;panel.innerHTML=`<div class="share-hero-silk">${hero?silk(hero,'large'):'<span class="share-clock">10</span>'}</div><div class="share-compact-copy"><span>${state.finished?'SHARE THE RESULT':state.ready?'SHARE THE FORM':'COMING SOON'}</span><b>${esc(state.title)}</b>${hero?`<strong>${esc(hero.display)}</strong>`:''}<small>${esc(state.sub)}${state.dividend?` · $${Number(state.dividend).toFixed(2)}`:''}</small></div><div class="share-support">${state.support.map(h=>`<span>${silk(h,'')}<small>${esc(h.display)}</small></span>`).join('')}</div>${state.ready?`<button class="share-card-button" id="shareGeoff"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 16V3m0 0 5 5m-5-5L7 8M5 13v7h14v-7"/></svg><span>Share card</span></button><div class="share-destinations" aria-label="Available through the phone share sheet"><img alt="WhatsApp" src="https://cdn.simpleicons.org/whatsapp/25D366"/><img alt="Instagram" src="https://cdn.simpleicons.org/instagram/E4405F"/><img alt="Messages" src="https://cdn.simpleicons.org/imessage/34C759"/></div>`:''}<span class="share-status" id="shareStatus"></span>`;
 if(state.ready)document.getElementById('shareGeoff').onclick=shareGeoff;
}
function geoffShareText(){const s=geoffShareState();return `${s.title} · Flemington R${race.number}\n${s.hero?.display||''}${sharePrice(s.hero,s)?` · ${sharePrice(s.hero,s)}`:''}\n${location.origin}/#race-${race.number}/form`}
async function loadShareImage(src){const img=new Image();img.src=src;await img.decode();return img}
async function drawShareSilk(c,h,x,y,size){if(!h)return;const img=await loadShareImage(`assets/silks-r${race.number}.png?meeting=${data.date}`),i=race.horses.findIndex(r=>r.name===h.name),w=img.width/race.horses.length;if(i>=0)c.drawImage(img,i*w,0,w,img.height,x,y,size,size)}
function canvasText(c,text,x,y,max,font,weight='900'){let size=font;c.font=`${weight} ${size}px Arial`;while(c.measureText(text).width>max&&size>32){size-=2;c.font=`${weight} ${size}px Arial`}c.fillText(text,x,y)}
async function buildGeoffShareCard(){
 const state=geoffShareState(),canvas=document.createElement('canvas');canvas.width=1080;canvas.height=1350;const c=canvas.getContext('2d'),accent=state.mood==='landed'?'#23834a':state.mood==='money'?'#b88414':state.mood==='off'?'#4c4c50':'#d9342b';
 c.fillStyle='#f4efe5';c.fillRect(0,0,1080,1350);c.fillStyle='#171717';c.fillRect(0,0,1080,345);c.fillStyle=accent;c.beginPath();c.moveTo(760,0);c.lineTo(1080,0);c.lineTo(1080,345);c.lineTo(930,345);c.closePath();c.fill();
 c.fillStyle='#fff';c.font='800 29px Arial';c.fillText('GEOFFS GUIDE',70,78);c.fillStyle='#b8b8bd';c.font='700 24px Arial';c.fillText(`FLEMINGTON · STAKES DAY · RACE ${race.number}`,70,128);c.fillStyle='#fff';canvasText(c,state.title,70,230,690,72);c.fillStyle='#d0d0d2';c.font='600 27px Arial';c.fillText(state.sub,70,286);
 const geoff=await loadShareImage('assets/geoff-source.jpg');c.save();c.beginPath();c.arc(915,172,92,0,Math.PI*2);c.clip();c.drawImage(geoff,55,445,480,480,823,80,184,184);c.restore();c.strokeStyle='#f4efe5';c.lineWidth=8;c.beginPath();c.arc(915,172,96,0,Math.PI*2);c.stroke();
 c.fillStyle='#fff';c.strokeStyle='#dfd7c8';c.lineWidth=2;c.beginPath();c.roundRect(55,400,970,535,34);c.fill();c.stroke();c.fillStyle=accent;c.fillRect(55,400,970,13);
 await drawShareSilk(c,state.hero,95,500,190);c.fillStyle='#777';c.font='800 23px Arial';c.fillText(state.finished?'SAVED PRE-RACE TIP':'TOP PICK',340,505);c.fillStyle='#171717';canvasText(c,state.hero?.display||'Unavailable',340,595,620,74);const price=sharePrice(state.hero,state);if(price){c.fillStyle=accent;c.beginPath();c.roundRect(340,635,Math.max(230,c.measureText(price).width+54),62,31);c.fill();c.fillStyle='#fff';c.font='900 26px Arial';c.fillText(price,368,676)}
 if(state.mood==='off'&&state.winner){c.fillStyle='#f0ece4';c.beginPath();c.roundRect(340,735,620,105,18);c.fill();c.fillStyle='#777';c.font='800 20px Arial';c.fillText('WINNER',370,772);c.fillStyle='#171717';c.font='900 36px Arial';c.fillText(M.title(state.winner.name),370,817)}else{c.fillStyle='#666';c.font='600 25px Arial';c.fillText(state.mood==='landed'?'Saved tip · winner':state.mood==='money'?`Saved tip · ${placingLabel(state.placing)}`:'Current model order',340,780)}
 if(state.support.length){c.fillStyle='#171717';c.font='800 22px Arial';c.fillText(state.finished?'OTHER SAVED CONTENDERS':'NEXT IN THE ORDER',70,1010);for(let i=0;i<state.support.length;i++){const h=state.support[i],x=70+i*480;await drawShareSilk(c,h,x,1050,92);c.fillStyle='#171717';canvasText(c,h.display,x+115,1102,325,34,'800');const p=sharePrice(h,state);if(p){c.fillStyle=accent;c.font='800 21px Arial';c.fillText(p,x+115,1140)}}}
 c.fillStyle='#777';c.font='22px Arial';c.fillText(state.finished?(state.dividend?'Official TABtouch tote dividend':'Official result · dividend unavailable'):'TABtouch original market snapshot',70,1260);c.fillStyle='#171717';c.font='800 22px Arial';c.fillText(location.host,70,1302);return new Promise(r=>canvas.toBlob(b=>r(new File([b],`geoffs-guide-r${race.number}.png`,{type:'image/png'})),'image/png'));
}
function geoffShareCard(){const s=geoffShareState(),key=`${lateMail?.runKey||'base'}-${race.number}-${s.mood}-${s.hero?.name||''}`;if(geoffCardCache.key!==key){geoffCardCache={key,promise:buildGeoffShareCard()}}return geoffCardCache.promise}
async function shareGeoff(){const status=document.getElementById('shareStatus');try{status.textContent='Preparing…';const file=await geoffShareCard();if(navigator.canShare?.({files:[file]})&&navigator.share){await navigator.share({files:[file],title:geoffShareState().title});status.textContent='Shared'}else if(navigator.share){await navigator.share({title:geoffShareState().title,text:geoffShareText(),url:`${location.origin}/#race-${race.number}/form`});status.textContent='Shared'}else{const a=document.createElement('a');a.href=URL.createObjectURL(file);a.download=file.name;a.click();status.textContent='Saved'}}catch(e){if(e.name!=='AbortError')status.textContent='Share unavailable'}}
